AMENDMENT_A_SHA256="495ad47fed0210ba4b495bdd86aa28784a5e5594df1e2648b6e04de8aa1fa379"
AMENDMENT_B_SHA256="fa85f7033226c497262418aa1c7bba0eddcb1a340febcf36a5643aa3bddc52bf"
AMENDMENT_C_SHA256="5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83"
AMENDMENT_D_SHA256="c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4"

